package akogen.fabric.v6;
import java.util.*;import java.io.*;
public class SharingPerformanceChecks{
 public static void main(String[]args)throws Exception{if(!SyncCodec.hash("abc".getBytes("UTF-8")).equals("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"))throw new AssertionError("Hash protocol changed");ByteArrayOutputStream out=new ByteArrayOutputStream();MqttLink link=new MqttLink("unused",8883,(t,b)->{});link.output=new DataOutputStream(out);Set<String> topics=new HashSet<String>(Arrays.asList("check/a","check/b"));link.subscriptions(topics);int bytes=out.size();for(int i=0;i<1000;i++)link.subscriptions(new HashSet<String>(topics));if(out.size()!=bytes)throw new AssertionError("Repeated subscription packets");link.subscriptions(Collections.singleton("check/b"));if(!link.subscriptions.equals(Collections.singleton("check/b"))||out.size()<=bytes)throw new AssertionError("Changed subscriptions ignored");CosmeticSync.Remote a=new CosmeticSync.Remote();UUID id=UUID.randomUUID();CosmeticSync.remotes.put(id,a);Collection<CosmeticSync.Remote> view=CosmeticSync.players();if(view!=CosmeticSync.players()||!view.contains(a))throw new AssertionError("Peer view copied each frame");CosmeticSync.remotes.remove(id);if(!view.isEmpty())throw new AssertionError("Stale peer view");boolean rejected=false;try{view.clear();}catch(UnsupportedOperationException expected){rejected=true;}if(!rejected)throw new AssertionError("Mutable renderer peer view");System.out.println("PASS identical SHA256 protocol, 1000 unchanged subscription updates emit zero extra bytes, changed topics update, no per-frame peer list copies");}
}
